#!/usr/bin/env python3\n\"\"\"รัน Backtest ของ XAUUSD Multi-Agent System และสร้างกราฟ\n\nใช้งาน:\n    python run_backtest.py\n\"\"\"\n\nfrom __future__ import annotations\n\nfrom pathlib import Path\n\nfrom backtest.engine import BacktestEngine, generate_synthetic_xauusd\nfrom backtest.charts import plot_backtest_result, plot_price_with_signals\nfrom agents.technical_analysis import TechnicalAnalysisAgent\nfrom agents.risk_management import RiskManagementAgent\n\n\ndef main() -> None:\n    print(\"=\" * 60)\n    print(\"XAUUSD Multi-Agent Backtest\")\n    print(\"Focus: Risk-Adjusted Return & Drawdown Control\")\n    print(\"=\" * 60)\n\n    print(\"\\n[1/4] Generating synthetic XAUUSD data (M15 + H1)...\")\n    df_m15, df_h1 = generate_synthetic_xauusd(n_bars=4000, start_price=2350.0, seed=42)\n    print(f\"      M15 bars: {len(df_m15)} | H1 bars: {len(df_h1)}\")\n    print(f\"      Period  : {df_m15.index[0]} → {df_m15.index[-1]}\")\n\n    print(\"\\n[2/4] Initializing Agents...\")\n    ta = TechnicalAnalysisAgent()\n    risk = RiskManagementAgent(\n        risk_per_trade=0.0075,\n        max_daily_drawdown=0.035,\n        max_open_positions=1,\n        min_reward_risk=1.6,\n        atr_sl_multiplier=1.8,\n        atr_tp_multiplier=3.0,\n    )\n\n    print(\"\\n[3/4] Running backtest...\")\n    engine = BacktestEngine(ta_agent=ta, risk_agent=risk, initial_equity=10000.0)\n    result = engine.run(df_m15, df_h1)\n\n    print(\"\\n[4/4] Results\")\n    print(\"-\" * 40)\n    print(f\"Initial Equity   : ${result.initial_equity:,.2f}\")\n    print(f\"Final Equity     : ${result.final_equity:,.2f}\")\n    print(f\"Total Return     : {result.total_return_pct:+.2f}%\")\n    print(f\"Max Drawdown     : {result.max_drawdown_pct:.2f}%\")\n    print(f\"Total Trades     : {result.total_trades}\")\n    print(f\"Win Rate         : {result.win_rate:.1f}%\")\n    print(f\"Profit Factor    : {result.profit_factor:.2f}\")\n    print(f\"Average R        : {result.avg_r:.2f}\")\n    print(f\"Sharpe (approx)  : {result.sharpe_approx:.2f}\")\n    print(\"-\" * 40)\n\n    out_dir = Path(\"backtest_output\")\n    out_dir.mkdir(exist_ok=True)\n\n    eq_path = plot_backtest_result(result, save_path=out_dir / \"equity_and_trades.png\")\n    print(f\"\\nSaved equity chart → {eq_path}\")\n\n    tail = df_m15.tail(500).copy()\n    price_path = plot_price_with_signals(tail, trades=result.trades, save_path=out_dir / \"price_signals.png\")\n    print(f\"Saved price chart  → {price_path}\")\n\n    print(\"\\n✅ Backtest completed successfully\")\n    print(\"หมายเหตุ: ข้อมูลเป็น synthetic — ผลลัพธ์ไม่ใช่การันตีกำไรจริง\")\n\n\nif __name__ == \"__main__\":\n    main()\n